function bought(id, pack) {
  const PACKS = {
    melee: ["Melee Weapons – Improvised & Household", "Shoestring Studios", "https://www.fab.com/listings/8345c73c-f74a-4f62-bd37-584c1ffb363f"],
    aid: ["First Aid Props", "Diogo Dzn", "https://www.fab.com/listings/de124f2c-90ce-4dff-aaad-d774c856e804"],
    cards: ["Electronic Access Keycards", "Ryptimal", "https://www.fab.com/listings/751a2939-9252-458e-b623-137d235c6ade"],
    doors: ["Laboratory doors", "Naked Singularity", "https://www.fab.com/listings/2298a577-0e34-4533-92b3-92d9b4a1fb26"],
    scope: ["SF Microscope", "Naked Singularity", "https://www.fab.com/listings/28815fc6-5816-4f7f-ba3f-28c13abe1e79"],
    bags: ["Survival Backpacks", "G-Star", "https://www.fab.com/listings/9544d129-7d4a-4447-9d77-4a383c27dc9b"],
    holster: ["Drop-Leg Holster with Pistol", "3dia", "https://www.fab.com/listings/313676c1-8e07-4f08-b44b-89b17d4c3df7"],
    vault: ["Bank Vault Door", "Dekogon", "https://www.fab.com/listings/c32b4895-b41f-483d-9ab5-d256806cfbb9"],
    xray: ["Modern Airport X-Ray Baggage Scanner (4K PBR)", "Wanted199514", "https://www.fab.com/listings/34b2f5e4-a9ca-42aa-933c-d56091a0fc0b"],
    bsc: ["Biosafety Cabinet", "Naked Singularity", "https://www.fab.com/listings/873fdab9-7bd8-479c-b88a-9a622c4febf1"],
    chemlab: ["Modular Modern Chemical Research Laboratory", "VadymHetiuk", "https://www.fab.com/listings/0ade58da-5a0d-4d84-a47f-afcdc9664167"],
  };
  const [name, author, page] = PACKS[pack];
  return { src: `file:assets/downloads/survivorz/originals/inbox/ready/${id}.glb`, fit: ["m"], source: page,
    licence: "Fab Standard (bought; no credit required, no redistribution)", credit: `"${name}" by ${author}, bought on Fab` };
}

